mapper.select:
SELECT FIN_PRODUCT.FINPROD_ID as finprodId, FIN_PRODUCT.FINPROD_MARKET_ID as finprodMarketId, FIN_PRODUCT_ADD.BOARD as board, MST_CUSTOMER_INFO.CUSTOMER_NAME as customerName, FIN_PRODUCT.FINPROD_ABBR as finprodAbbr, FIN_PRODUCT.TRADE_MARKET as tradeMarket, C.S_SHARES as sShares, C.C_SHARES as cShares, FIN_PRODUCT.MDATE as mDate, FIN_PRODUCT.VDATE as vDate, FIN_PRODUCT.CCY as ccy, FIN_PRODUCT_ADD.SH_OR_ZH as shOrZh, FIN_PRODUCT_ADD.IS_MARGIN_FINPROD as isMarginFinprod FROM FIN_PRODUCT LEFT JOIN MST_CUSTOMER_INFO ON FIN_PRODUCT.ISSUER = MST_CUSTOMER_INFO.CUSTOMER_ID LEFT JOIN FIN_PRODUCT_ADD ON FIN_PRODUCT_ADD.FINPROD_ID = FIN_PRODUCT.FINPROD_ID LEFT JOIN (select a.S_SHARES ,a.c_shares,a.shares_id,a.deal_date from ( select max(deal_date) deal_date,shares_id from mst_share_price where DATE_FORMAT(deal_date,'%Y-%m-%d') < #{sysDate,jdbcType=VARCHAR} group by shares_id ) b left join mst_share_price a on a.shares_id=b.shares_id and a.deal_date=b.deal_date ) C ON C.SHARES_ID = FIN_PRODUCT.FINPROD_MARKET_ID
AND FIN_PRODUCT.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
and FIN_PRODUCT.FINPROD_MARKET_ID LIKE CONCAT('%',CONCAT(#{finprodMarketId,jdbcType=VARCHAR},'%'))
AND FIN_PRODUCT_ADD.BOARD = #{board,jdbcType=VARCHAR}
AND MST_CUSTOMER_INFO.CUSTOMER_NAME = #{customerName,jdbcType=VARCHAR}
AND FIN_PRODUCT.FINPROD_ABBR = #{finProdAbbr,jdbcType=VARCHAR}
AND FIN_PRODUCT.TRADE_MARKET = #{tradeMarket,jdbcType=VARCHAR}
AND FIN_PRODUCT_ADD.SH_OR_ZH = #{shOrZh,jdbcType=VARCHAR}
AND FIN_PRODUCT_ADD.IS_MARGIN_FINPROD = #{isMarginFinprod,jdbcType=VARCHAR}
AND FIN_PRODUCT.CCY = #{ccy,jdbcType=VARCHAR}
AND FIN_PRODUCT.VDATE >= STR_TO_DATE(#{vdatestart},'%Y-%m-%d')
AND FIN_PRODUCT.VDATE <= STR_TO_DATE(#{vdateend},'%Y-%m-%d')
and FIN_PRODUCT.FINPROD_TYPE2 = 'F10' and 1=1

SELECT FIN_PRODUCT.FINPROD_ID as finprodId, FIN_PRODUCT.FINPROD_MARKET_ID as finprodMarketId, FIN_PRODUCT_ADD.BOARD as board, FIN_PRODUCT.ISSUER as issuer, FIN_PRODUCT.CALENDAR_ID as calendarId, MST_CUSTOMER_INFO.CUSTOMER_NAME as customerName, FIN_PRODUCT.FINPROD_ABBR as finprodAbbr, FIN_PRODUCT.TRADE_MARKET as tradeMarket, C.S_SHARES as sShares, C.C_SHARES as cShares, FIN_PRODUCT.MDATE as mDate, FIN_PRODUCT.VDATE as vDate, FIN_PRODUCT.CCY as ccy, FIN_PRODUCT_ADD.SH_OR_ZH as shOrZh, FIN_PRODUCT_ADD.IS_MARGIN_FINPROD as isMarginFinprod FROM FIN_PRODUCT LEFT JOIN MST_CUSTOMER_INFO ON FIN_PRODUCT.ISSUER = MST_CUSTOMER_INFO.CUSTOMER_ID LEFT JOIN FIN_PRODUCT_ADD ON FIN_PRODUCT_ADD.FINPROD_ID = FIN_PRODUCT.FINPROD_ID LEFT JOIN ( SELECT * FROM MST_SHARE_PRICE A WHERE DEAL_DATE IN ( SELECT MAX (DEAL_DATE) FROM MST_SHARE_PRICE b WHERE A .SHARES_ID = b.SHARES_ID AND DATE_FORMAT(DEAL_DATE,'%Y-%m-%d') < #{sysDate,jdbcType=VARCHAR} GROUP BY SHARES_ID ) ORDER BY SHARES_ID ) C ON C.SHARES_ID = FIN_PRODUCT.FINPROD_MARKET_ID
AND FIN_PRODUCT.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
and FIN_PRODUCT.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F10,jdbcType=VARCHAR}
